import anthropic
client = anthropic.Anthropic(max_retries=2)  # default is 2
try:
    msg = client.with_options(max_retries=5).messages.create(
        model="claude-opus-5-5", max_tokens=1024,
        messages=[{"role": "user", "content": "Hello, Claude"}],
    )
except anthropic.RateLimitError:
    print("429: wait retry-after, then retry")
except anthropic.APIConnectionError as e:
    print("could not reach server", e.__cause__)
except anthropic.APIStatusError as e:
    print(e.status_code, e.response)

