import Anthropic from "@anthropic-ai/sdk";
const client = new Anthropic({ maxRetries: 2 }); // apiKey defaults to process.env.ANTHROPIC_API_KEY
const message = await client.messages.create({
  model: "claude-opus-5-5",
  max_tokens: 1000,
  messages: [{ role: "user", content: "Hello, Claude" }],
});
for (const block of message.content) {
  if (block.type === "text") console.log(block.text);
}

import base64, anthropic
client = anthropic.Anthropic()

with open("photo.jpg", "rb") as f:
    image_data = base64.standard_b64encode(f.read()).decode("utf-8")

message = client.messages.create(
    model="claude-opus-5-5",
    max_tokens=1024,
    messages=[{
        "role": "user",
        "content": [
            {"type": "image", "source": {
                "type": "base64",
                "media_type": "image/jpeg",
                "data": image_data,
            }},
            {"type": "text", "text": "Describe this image."},
        ],
    }],
)
print(message.content[0].text)

import json
response = client.messages.create(
    model="claude-opus-5-5",
    max_tokens=1024,
    messages=[{"role": "user", "content": "Extract: John Smith (john@example.com) wants an Enterprise demo Tuesday 2pm."}],
    output_config={"format": {
        "type": "json_schema",
        "schema": {
            "type": "object",
            "properties": {
                "name": {"type": "string"},
                "email": {"type": "string"},
                "demo_requested": {"type": "boolean"},
            },
            "required": ["name", "email", "demo_requested"],
            "additionalProperties": False,
        },
    }},
)
text = next(b.text for b in response.content if b.type == "text")
contact = json.loads(text)

import time, anthropic
client = anthropic.Anthropic()

batch = client.messages.batches.create(requests=[
    {"custom_id": "my-first-request", "params": {
        "model": "claude-opus-5-5", "max_tokens": 1024,
        "messages": [{"role": "user", "content": "Hello, world"}]}},
    {"custom_id": "my-second-request", "params": {
        "model": "claude-opus-5-5", "max_tokens": 1024,
        "messages": [{"role": "user", "content": "Hi again, friend"}]}},
])

while True:
    batch = client.messages.batches.retrieve(batch.id)
    if batch.processing_status == "ended":
        break
    time.sleep(60)

for entry in client.messages.batches.results(batch.id):
    if entry.result.type == "succeeded":
        print(entry.custom_id, entry.result.message.content)
